exercise.referenceSolution:
#include <iostream>

bool above(int value, int threshold = 80) { return value > threshold; }
int main() {
    int value{}, threshold{};
    if (!(std::cin >> value >> threshold)) return 1;
    std::cout << above(value) << ' ' << above(value, threshold) << '\n';
}
